import csv
import re

_QUANTITY_RE = re.compile(r'[+-]?[0-9]{1,10}')


def _validate_limits(max_rows, max_labels):
    if isinstance(max_rows, bool) or isinstance(max_labels, bool):
        raise ValueError('limits must be positive integers, not bool')
    if not isinstance(max_rows, int) or not isinstance(max_labels, int):
        raise ValueError('limits must be positive integers')
    if max_rows < 1 or max_labels < 1:
        raise ValueError('limits must be positive integers')


def _validate_label(raw, row_num):
    if '\r' in raw or '\n' in raw:
        raise ValueError(f'row {row_num}: label contains CR or LF')
    label = raw.strip()
    if not (1 <= len(label) <= 120):
        raise ValueError(f'row {row_num}: label length out of range')
    return label


def _validate_quantity(raw, row_num):
    if not _QUANTITY_RE.fullmatch(raw):
        raise ValueError(f'row {row_num}: invalid quantity')
    value = int(raw)
    if abs(value) > 1000000000:
        raise ValueError(f'row {row_num}: quantity magnitude exceeds limit')
    return value


def summarize(stream, max_rows=1000000, max_labels=1000) -> list:
    _validate_limits(max_rows, max_labels)

    reader = csv.reader(stream, strict=True)
    try:
        header = next(reader)
    except StopIteration:
        return []
    except Exception as exc:
        raise ValueError(f'row 1: {exc}') from exc

    if header != ['label', 'quantity']:
        raise ValueError(f'row 1: invalid header')

    totals = {}
    data_count = 0

    try:
        for row in reader:
            data_count += 1
            if data_count > max_rows:
                raise ValueError(f'row {data_count}: exceeds max_rows')

            if len(row) != 2:
                raise ValueError(f'row {data_count + 1}: invalid field count')

            raw_label, raw_quantity = row
            label = _validate_label(raw_label, data_count + 1)
            quantity = _validate_quantity(raw_quantity, data_count + 1)

            if label not in totals:
                if len(totals) >= max_labels:
                    raise ValueError(f'row {data_count + 1}: exceeds max_labels')
                totals[label] = 0
            totals[label] += quantity
    except UnicodeDecodeError as exc:
        raise ValueError(f'row {data_count + 1}: {exc}') from exc
    except csv.Error as exc:
        raise ValueError(f'row {data_count + 1}: {exc}') from exc

    result = []
    for label in sorted(totals):
        result.append({'label': label, 'quantity': totals[label]})
    return result
